Sort by start time, then sweep with a min-heap of end times. For each booking, pop every end that's less than or equal to the current start, since touching counts as free. Push the current end, and the heap size is the rooms in use. The max over the sweep is the answer.

```js
function minRooms(bookings) {
  if (bookings.length === 0) return 0;
  const sorted = [...bookings].sort((a, b) => a[0] - b[0]);
  const heap = []; // min-heap of end times

  const push = (x) => {
    heap.push(x);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heap[p] <= heap[i]) break;
      [heap[p], heap[i]] = [heap[i], heap[p]];
      i = p;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < heap.length && heap[l] < heap[m]) m = l;
        if (r < heap.length && heap[r] < heap[m]) m = r;
        if (m === i) break;
        [heap[i], heap[m]] = [heap[m], heap[i]];
        i = m;
      }
    }
    return top;
  };

  let rooms = 0;
  for (const [start, end] of sorted) {
    while (heap.length && heap[0] <= start) pop();
    push(end);
    rooms = Math.max(rooms, heap.length);
  }
  return rooms;
}
```

O(n log n) time, O(n) space. The `<=` is what makes `[[1,4],[4,6]]` come out as 1.

